// Portfolio Rebalancer Logic
const portfolio = $('Get Portfolio').first().json;
const trades = $('Get Trade History').first().json;
const ticker = $('Get BTC Price').first().json;
const status = $('Get Status').first().json;

// Safety check
if (status.trading_halted) {
  return [{ json: { action: 'skip', reason: 'Trading halted: ' + status.halt_reason } }];
}

// Get current holdings
const usdBalance = portfolio.balances?.ZUSD?.amount || 0;
const btcBalance = portfolio.balances?.XXBT?.amount || 0;
const currentPrice = ticker.tickers?.XXBTZUSD?.price || 0;

if (!currentPrice || currentPrice <= 0) {
  return [{ json: { action: 'skip', reason: 'Could not get current price' } }];
}

// Calculate portfolio composition
const btcValueUsd = btcBalance * currentPrice;
const totalValueUsd = usdBalance + btcValueUsd;
const btcPct = (btcValueUsd / totalValueUsd) * 100;

// Calculate cost basis from trade history
let totalBtcBought = 0;
let totalCostUsd = 0;
const btcTrades = (trades.trades || []).filter(t => t.pair === 'XXBTZUSD' && t.side === 'buy');
for (const trade of btcTrades) {
  totalBtcBought += parseFloat(trade.volume);
  totalCostUsd += parseFloat(trade.cost);
}
const avgCostBasis = totalBtcBought > 0 ? totalCostUsd / totalBtcBought : currentPrice;
const unrealizedPnlPct = ((currentPrice - avgCostBasis) / avgCostBasis) * 100;

// Rebalance thresholds
const TARGET_BTC_PCT = 50;  // Target 50% in BTC
const MAX_BTC_PCT = 65;     // Rebalance if BTC > 65%
const MIN_PROFIT_PCT = 5;   // Only take profit if up > 5%
const SELL_PORTION = 0.25;  // Sell 25% of excess

let action = 'skip';
let sellAmount = 0;
let reason = '';

// Check if rebalance needed
if (btcPct > MAX_BTC_PCT && unrealizedPnlPct > MIN_PROFIT_PCT) {
  // Calculate how much to sell to get back toward target
  const excessBtcValue = btcValueUsd - (totalValueUsd * TARGET_BTC_PCT / 100);
  const sellValueUsd = excessBtcValue * SELL_PORTION;
  sellAmount = sellValueUsd / currentPrice;

  // Only sell if meaningful amount (> $5)
  if (sellValueUsd >= 5) {
    action = 'sell';
    reason = `Rebalance: BTC at ${btcPct.toFixed(1)}% (>${MAX_BTC_PCT}%), up ${unrealizedPnlPct.toFixed(1)}% from cost basis. Selling $${sellValueUsd.toFixed(2)} worth.`;
  } else {
    reason = `Near threshold but sell amount too small ($${sellValueUsd.toFixed(2)}). Waiting.`;
  }
} else if (btcPct > MAX_BTC_PCT) {
  reason = `BTC at ${btcPct.toFixed(1)}% but only ${unrealizedPnlPct.toFixed(1)}% profit. Need >${MIN_PROFIT_PCT}% to sell.`;
} else {
  reason = `Balanced: BTC ${btcPct.toFixed(1)}%, profit ${unrealizedPnlPct.toFixed(1)}%. No action needed.`;
}

return [{
  json: {
    action,
    sell_amount_btc: sellAmount,
    reason,
    portfolio: {
      usd: usdBalance,
      btc: btcBalance,
      btc_value_usd: btcValueUsd,
      total_value_usd: totalValueUsd,
      btc_pct: btcPct
    },
    cost_basis: {
      avg_price: avgCostBasis,
      current_price: currentPrice,
      unrealized_pnl_pct: unrealizedPnlPct,
      total_invested: totalCostUsd
    },
    thresholds: {
      target_btc_pct: TARGET_BTC_PCT,
      max_btc_pct: MAX_BTC_PCT,
      min_profit_pct: MIN_PROFIT_PCT
    },
    timestamp: new Date().toISOString()
  }
}];

const decision = $('Rebalance Logic').first().json;
const result = $('Execute Sell').first().json;
console.log('=== REBALANCE EXECUTED ===');
console.log('Action:', decision.action);
console.log('Reason:', decision.reason);
console.log('BTC%:', decision.portfolio.btc_pct.toFixed(1));
console.log('Result:', JSON.stringify(result));
return [{ json: { type: 'rebalance_sell', ...decision, result } }];

